from __future__ import annotations

import ast
import calendar
import csv
import json
from bisect import bisect_right
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET_DIR = Path("/app/dataset")
EMPLOYEES_CSV = DATASET_DIR / "employees.csv"
TASKS_CSV = DATASET_DIR / "tasks.csv"
TIMESHEET_CSV = DATASET_DIR / "timesheet.csv"


def round_half_up(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def levenshtein(a: str, b: str) -> int:
    previous = list(range(len(b) + 1))
    for i, char_a in enumerate(a, start=1):
        current = [i]
        for j, char_b in enumerate(b, start=1):
            current.append(
                min(
                    previous[j] + 1,
                    current[j - 1] + 1,
                    previous[j - 1] + (char_a != char_b),
                )
            )
        previous = current
    return previous[-1]


def parse_clamped_date(raw: str) -> date:
    year, month, day = map(int, raw.split("-"))
    return date(year, month, min(day, calendar.monthrange(year, month)[1]))


def parse_tasks(raw: str) -> list[int]:
    normalized = raw.strip()
    if not normalized.startswith("["):
        normalized = "[" + normalized
    if not normalized.endswith("]"):
        normalized = normalized + "]"

    parsed = ast.literal_eval(normalized)
    if not isinstance(parsed, list):
        parsed = [parsed]
    return [int(item) for item in parsed]


def first_weekday_in_month(year: int, month: int, weekday: int) -> date:
    current = date(year, month, 1)
    while current.weekday() != weekday:
        current += timedelta(days=1)
    return current


def month_after(value: date) -> tuple[int, int]:
    if value.month == 12:
        return value.year + 1, 1
    return value.year, value.month + 1


def load_employees() -> dict[str, Decimal]:
    with EMPLOYEES_CSV.open(newline="", encoding="utf-8") as handle:
        return {
            row["PESEL"]: Decimal(row["hourly_rate"])
            for row in csv.DictReader(handle)
        }


def build_employee_id_mapper(valid_ids: list[str]):
    def mapper(raw_id: str) -> str | None:
        if raw_id in valid_ids_set:
            return raw_id

        scores = sorted((levenshtein(raw_id, valid_id), valid_id) for valid_id in valid_ids)
        if not scores:
            return None
        best_score, best_id = scores[0]
        second_score = scores[1][0] if len(scores) > 1 else None
        if second_score is None or best_score < second_score:
            return best_id
        return None

    valid_ids_set = set(valid_ids)
    return mapper


def load_task_pays() -> dict[int, Decimal]:
    with TASKS_CSV.open(newline="", encoding="utf-8") as handle:
        return {
            int(row["task_id"]): Decimal(row["pay_per_completion"])
            for row in csv.DictReader(handle)
        }


def cleaned_rows() -> tuple[list[str], dict[str, Decimal], list[tuple[date, str, Decimal]]]:
    employee_rates = load_employees()
    employee_ids = list(employee_rates)
    task_pays = load_task_pays()
    map_employee_id = build_employee_id_mapper(employee_ids)

    rows: list[tuple[date, str, Decimal]] = []
    with TIMESHEET_CSV.open(newline="", encoding="utf-8") as handle:
        for raw_row in csv.DictReader(handle):
            employee_id = map_employee_id(raw_row["employee_id"])
            if employee_id is None:
                continue

            try:
                work_date = parse_clamped_date(raw_row["date"])
                hours_worked = Decimal(raw_row["hours_worked"])
                performed_tasks = parse_tasks(raw_row["performed_tasks"])
            except Exception:
                continue

            if hours_worked < 0:
                continue

            hourly_rate = employee_rates[employee_id]
            bonus = sum(task_pays[task_id] for task_id in performed_tasks if task_id in task_pays)
            rows.append((work_date, employee_id, hours_worked * hourly_rate + bonus))

    rows.sort(key=lambda item: item[0])
    return employee_ids, employee_rates, rows


def billing_period_starts(rows: list[tuple[date, str, Decimal]]) -> list[date]:
    earliest = rows[0][0]
    latest = rows[-1][0]
    anchor_weekday = earliest.weekday()

    starts = [earliest]
    year, month = month_after(earliest)
    while True:
        current = first_weekday_in_month(year, month, anchor_weekday)
        starts.append(current)
        if current > latest:
            break
        year, month = month_after(current)
    return starts


def answer() -> dict[str, list[int]]:
    employee_ids, _, rows = cleaned_rows()
    starts = billing_period_starts(rows)
    period_count = len(starts) - 1

    totals: dict[str, list[Decimal]] = {
        employee_id: [Decimal("0") for _ in range(period_count)]
        for employee_id in employee_ids
    }

    for work_date, employee_id, amount in rows:
        period_index = bisect_right(starts, work_date) - 1
        if 0 <= period_index < period_count:
            totals[employee_id][period_index] += amount

    return {
        employee_id: [round_half_up(amount) for amount in totals[employee_id]]
        for employee_id in employee_ids
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as handle:
        json.dump(answer(), handle, ensure_ascii=False)
